return array(
	'ab_intro' => 'Madoka Childcare ist eine Betreuungseinrichtung für Babys und Kleinkinder berufstätiger Familien, in einem Backsteinhaus in der Linden Row in Ranelagh. Sie ist seit 2015 geöffnet, mit 39 Plätzen für Kinder von 4 Monaten bis 4 Jahren.',
	'ab_h1' => 'Ein kleines Haus für kleine Menschen',
	'ab_b1' => 'Madoka Quinlan hat Madoka Childcare 2015 eröffnet, nach zwölf Jahren als Gruppenleiterin. Berufstätige Eltern sollten ein Haus haben, in dem dieselben Erwachsenen ein Kind von der Tür um 07:30 bis zur Abholung sehen. Die Einrichtung ist ein zweistöckiges Backsteinhaus mit Garten in der 12 Linden Row, Ranelagh, Dublin 6. Wir nehmen Kinder von 4 Monaten bis 4 Jahren auf, mit 39 Plätzen in drei Räumen. Geöffnet ist Montag bis Freitag, 07:30 bis 18:30. An Wochenenden, an irischen Feiertagen und vom 24. Dezember bis 1. Januar bleiben wir geschlossen. Der Tag selbst ist leicht zu benennen: Hallo an der Tür, Frühstück, Zeit draußen, Mittagessen, Ruhe, Atelierspiel und eine Geschichte vor dem Heimgehen. Unsere Personalausstattung beschreiben wir als unsere eigene Richtlinie. Wir stellen sie nicht als Rangfolge dar, und wir sprechen nicht über spätere Schulerfolge.',
	'ab_h2' => 'Warum drei Räume',
